-- Tenancy. The organization is the tenant root (its tenant_id is its own id); every other
-- row carries the tenant_id of its organization. Ids are UUIDv7 generated by the app, also
-- on offline devices, so no column has a database default for id.
--
-- Children reference parents by (tenant_id, id), never by id alone: foreign key checks
-- bypass row level security, so a single-column key would let tenant A attach rows to a
-- parent of tenant B just by knowing its id. The (tenant_id, id) unique key on every table
-- makes that possible and doubles as the tenant-leading index.
--
-- created_by is the app_user that created the row, kept as plain audit data without a
-- foreign key, so a row synced from an offline device never waits on the user row.

CREATE TABLE organization (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  version integer NOT NULL DEFAULT 1,
  CONSTRAINT organization_tenant_id_id_key UNIQUE (tenant_id, id),
  CONSTRAINT organization_is_its_own_tenant CHECK (tenant_id = id)
);

CREATE TABLE brand (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  version integer NOT NULL DEFAULT 1,
  CONSTRAINT brand_tenant_id_id_key UNIQUE (tenant_id, id),
  CONSTRAINT brand_organization_fkey FOREIGN KEY (tenant_id) REFERENCES organization (id)
);

-- A fixed UTC offset instead of a time-zone name, so every device derives the same local
-- time. The business day starts at 04:00 by default, so sales after midnight still count
-- toward the evening they belong to.
CREATE TABLE branch (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  brand_id uuid NOT NULL,
  name text NOT NULL,
  utc_offset_minutes integer NOT NULL DEFAULT 420,
  business_day_start_minute integer NOT NULL DEFAULT 240,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  version integer NOT NULL DEFAULT 1,
  CONSTRAINT branch_tenant_id_id_key UNIQUE (tenant_id, id),
  CONSTRAINT branch_brand_fkey FOREIGN KEY (tenant_id, brand_id) REFERENCES brand (tenant_id, id),
  CONSTRAINT branch_utc_offset_minutes_range CHECK (utc_offset_minutes BETWEEN -720 AND 840),
  CONSTRAINT branch_business_day_start_minute_range CHECK (business_day_start_minute BETWEEN 0 AND 1439)
);

CREATE INDEX branch_tenant_id_brand_id_idx ON branch (tenant_id, brand_id);

CREATE TABLE area (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  branch_id uuid NOT NULL,
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  version integer NOT NULL DEFAULT 1,
  CONSTRAINT area_tenant_id_id_key UNIQUE (tenant_id, id),
  CONSTRAINT area_branch_fkey FOREIGN KEY (tenant_id, branch_id) REFERENCES branch (tenant_id, id)
);

CREATE INDEX area_tenant_id_branch_id_idx ON area (tenant_id, branch_id);

CREATE TABLE dining_table (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  area_id uuid NOT NULL,
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  version integer NOT NULL DEFAULT 1,
  CONSTRAINT dining_table_tenant_id_id_key UNIQUE (tenant_id, id),
  CONSTRAINT dining_table_area_fkey FOREIGN KEY (tenant_id, area_id) REFERENCES area (tenant_id, id)
);

CREATE INDEX dining_table_tenant_id_area_id_idx ON dining_table (tenant_id, area_id);

CREATE TABLE device (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  branch_id uuid NOT NULL,
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  version integer NOT NULL DEFAULT 1,
  CONSTRAINT device_tenant_id_id_key UNIQUE (tenant_id, id),
  CONSTRAINT device_branch_fkey FOREIGN KEY (tenant_id, branch_id) REFERENCES branch (tenant_id, id)
);

CREATE INDEX device_tenant_id_branch_id_idx ON device (tenant_id, branch_id);

CREATE TABLE app_user (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  display_name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  version integer NOT NULL DEFAULT 1,
  CONSTRAINT app_user_tenant_id_id_key UNIQUE (tenant_id, id),
  CONSTRAINT app_user_organization_fkey FOREIGN KEY (tenant_id) REFERENCES organization (id)
);
